pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public { 
        deployer = address(this);
        c = new C(); 
    }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        // Record initial owner (set by constructor to deployer)
        address initialOwner = address(this);

        // Execute owned() from arbitrary caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("owned()"));

        // After the call, owner should equal the contract deployer (unchanged by owned())
        address ownerAfter = c.owner();

        // The rule: if the call succeeded, owner must be the deployer;
        // but the bug causes revert, so ownerAfter is irrelevant; we assert only on successful call
        if (success) {
            assertTrue(ownerAfter == deployer, "Owner should remain deployer after owned()");
        } else {
            // Call reverted, but still owner must be unchanged from initial
            // (since modifier reverted before assignment, but no assignment exists in owned())
            // Actually, owned() does nothing; so owner must still be deployer
            assertTrue(ownerAfter == deployer, "Owner must remain deployer even if owned() reverts");
        }
    }
}

